<?php
namespace App\Http\Controllers;
use App\Models\DiningSession; use App\Models\Order; use App\Models\OrderItem; use App\Models\Product; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class OrderController extends Controller { public function store(Request $r,int $sid){$d=$r->validate(['items'=>'required|array|min:1','items.*.menuItemId'=>'required|integer','items.*.quantity'=>'required|integer|min:1|max:100','items.*.note'=>'nullable|string|max:500']);$s=DiningSession::findOrFail($sid);if($s->status==='Closed')return response()->json(['message'=>'الجلسة مغلقة'],409);$o=DB::transaction(function()use($s,$d){$o=Order::create(['restaurant_id'=>$s->restaurant_id,'dining_session_id'=>$s->id,'status'=>'Pending','submitted_at'=>now()]);foreach($d['items'] as $i){$p=Product::where('restaurant_id',$s->restaurant_id)->whereKey($i['menuItemId'])->where('is_available',true)->firstOrFail();OrderItem::create(['order_id'=>$o->id,'product_id'=>$p->id,'quantity'=>$i['quantity'],'unit_price'=>$p->price,'note'=>$i['note']??null]);}$s->update(['status'=>'Ordering']);return $o;});return response()->json(['data'=>$o->load('items.product')],201);} public function sessionOrders(int $sid){$s=DiningSession::findOrFail($sid);return response()->json(['data'=>$s->orders()->with('items.product')->latest()->get()]);} public function kitchen(Request $r){$q=Order::with(['session.table','items.product'])->where('restaurant_id',$r->user()->restaurant_id)->whereIn('status',['Pending','Preparing','Ready']);return response()->json(['data'=>$q->orderBy('submitted_at')->get()]);} public function status(Request $r,int $id){$o=Order::where('restaurant_id',$r->user()->restaurant_id)->findOrFail($id);$d=$r->validate(['status'=>'required|in:Pending,Preparing,Ready,Served']);$o->update(['status'=>$d['status'],'ready_at'=>$d['status']==='Ready'?now():$o->ready_at]);$o->session->update(['status'=>$d['status']]);return response()->json(['data'=>$o->load('items.product')]);} public function owner(Request $r){return response()->json(Order::with(['session.table','items.product'])->where('restaurant_id',$r->user()->restaurant_id)->latest('submitted_at')->paginate(30));}}
